import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"project/ holds process artifacts; published docs live in the org docs/","description":"","frontmatter":{"title":"`project/` holds process artifacts; published docs live in the org `docs/`","type":"adr","date":"2026-10-28T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","status":"accepted","applies_to":"all repos with a `project` branch; `docs` (the published hub)"},"headers":[],"relativePath":"handl/project/adrs/0162-project-folder-taxonomy.md","filePath":"vendored/handl/project/adrs/0162-project-folder-taxonomy.md"}'),a={name:`handl/project/adrs/0162-project-folder-taxonomy.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0162-project-holds-process-artifacts-published-docs-live-in-the-org-docs" tabindex="-1">ADR-0162: <code>project/</code> holds process artifacts; published docs live in the org <code>docs/</code> <a class="header-anchor" href="#adr-0162-project-holds-process-artifacts-published-docs-live-in-the-org-docs" aria-label="Permalink to “ADR-0162: project/ holds process artifacts; published docs live in the org docs/”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><p><strong><code>project/</code> holds process artifacts only.</strong> Explanations, tutorials, how-to guides and reference are published documentation and live in the org <code>docs</code> repo (each repo&#39;s <code>docs/site/</code>, vendored into the hub). A <code>project/docs/</code> directory is never created.</p></li><li><p><strong>The top-level set is closed</strong>, identical in every repo:</p><table tabindex="0"><thead><tr><th>entry</th><th>answers</th><th>lifetime</th></tr></thead><tbody><tr><td><code>adrs/</code></td><td><em>why</em> — the decision and what was rejected</td><td>append-only, permanent</td></tr><tr><td><code>design/</code></td><td><em>how</em> — mechanism, algorithms, state machines</td><td>until code is the spec</td></tr><tr><td><code>rfcs/</code></td><td><em>when</em> — the port plan to Handl</td><td>until the port lands</td></tr><tr><td><code>tasks/</code>, <code>TODO.md</code></td><td><em>who/what next</em></td><td>consumed</td></tr><tr><td><code>BACKLOG.md</code></td><td><em>not now</em> — accepted, unscheduled</td><td>reaped quarterly</td></tr><tr><td><code>parked.yaml</code></td><td><em>retired</em> — ideas deliberately not built</td><td>permanent, with unpark trigger</td></tr><tr><td><code>notes/</code></td><td><em>what we found</em> — investigations, measurements</td><td>promoted or deleted</td></tr><tr><td><code>reports/</code></td><td><em>what we measured</em> — audits, sweeps</td><td>dated, immutable</td></tr><tr><td><code>retros/</code></td><td><em>what went wrong</em> — process post-mortems</td><td>dated, immutable</td></tr><tr><td><code>references.md</code></td><td><em>what we depend on</em> — other repos&#39; ADR ids</td><td>maintained</td></tr><tr><td><code>docs-split.yaml</code></td><td><em>where things live</em> — assignment manifest</td><td>maintained</td></tr></tbody></table><p>Anything else is a layout error, unless the repo declares it under <code>## Local entries</code> in <code>project/README.md</code> (one line: name — purpose). Core entries mean the same thing everywhere; local entries are a documented extension, not a free-for-all.</p></li><li><p><strong>One artifact answers one question.</strong> A document that answers two is split; a document that answers none is deleted.</p></li><li><p><strong>Dated vs living.</strong> <code>notes/</code>, <code>reports/</code>, <code>retros/</code> are dated artifacts and are never edited afterwards; the date lives in the frontmatter (<code>date:</code>), never in the filename (ADR-0163). <code>adrs/</code>, <code>design/</code>, <code>references.md</code> are current-truth and carry their creation/decision date in frontmatter only. Filenames are stable labels — a file is never renamed to carry a date.</p></li><li><p><strong><code>design/</code></strong> is either named after the ADR it elaborates (<code>NNNN-slug.md</code>) or carries a <code>- Refs: ADR-NNNN, …</code> line under its title. Once the ADR&#39;s <code>## Enforcement</code> names the code that makes it true, the design doc may be deleted — git keeps it.</p></li><li><p><strong>A rejected design produces an ADR, never a note.</strong> <code>notes/</code> is a one-cycle scratchpad: promote to <code>design/</code>/<code>adrs/</code> or delete.</p></li><li><p><strong>No copies across repos.</strong> Cross-repo references are ids + URLs (ADR-0129 §7). A <code>project/</code> tree contains only its own repo&#39;s artifacts.</p></li><li><p><strong>One <code>project/</code> per repo, on its <code>project</code> branch</strong> (ADR-0129 §1), mounted as a gitignored worktree. The org <code>project</code> repo holds <strong>org-wide artifacts only</strong> — cross-repo plans, org policy, the docs manifest — never a repo&#39;s own ADRs and never a staging copy of them.</p></li><li><p><code>scripts/check-project-layout.py</code> enforces 1, 2, 7 and 8; <code>scripts/project-frontmatter.py</code> enforces the metadata schema (ADR-0163); <code>scripts/check-adrs.py</code> enforces the ADR side (ADR-0161).</p></li><li><p><code>project/README.md</code> states this map in one screen and links this ADR.</p></li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>There are four layouts in use today. <code>host/project</code> has <code>adrs assets design notes reports tasks</code>; <code>kit-data-prelude/project</code> has <code>adrs tasks references.md</code>; <code>graphopt/project</code> adds <code>plans</code>, <code>retros</code>, <code>GOALS.md</code> and a <code>research_lab_notebook.md</code>; the org <code>project</code> repo adds <code>c/ web/ plans/ defining-handl/ docs/</code>, three of which carry their own <code>adrs/</code>. Consequences already paid: ADR-0150 and ADR-0151 exist twice (embedded copies, in violation of ADR-0129 §7), nobody can predict where a new document belongs so it gets written twice, and process documents sit in the tree the docs site sweeps.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>One flat directory with filename prefixes</strong> — unreadable at 300 files and loses the &quot;this is consumed, that is permanent&quot; distinction.</li><li><strong>Document the map inside <code>project/docs/</code></strong> — it would be published, then drift from the site&#39;s four quadrants.</li><li><strong>Let each repo pick its own layout</strong> — that is the current state.</li><li><strong>Enforce by review culture alone</strong> — already tried; the drift is the evidence.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>host/project</code> lands clean: <code>assets/</code> folded into <code>notes/</code>, undated <code>notes/</code>/<code>reports/</code> take their git creation date in frontmatter (never in the filename), <code>design/</code> files given <code>Refs:</code> lines.</li><li><code>graphopt</code> declares <code>plans/</code> and <code>GOALS.md</code> as local entries (a research repo&#39;s workstream records and goal ledger), moves its lab notebook into <code>notes/</code>, and keeps <code>retros/</code> as-is.</li><li>The org <code>project</code> repo holds only org-wide artifacts: the <code>c/</code> and <code>web/</code> trees moved to their own repos (<code>handl-lang/c</code>, <code>handl-lang/web</code>), each with a <code>project</code> branch and <code>plans/</code> staying behind as the cross-repo record.</li><li><code>project/docs/</code> is gone (published docs belong to the <code>docs</code> hub), as are the duplicated <code>plans/adrs/0150</code>, <code>0151</code>.</li><li>Contributors get a single question to answer — &quot;what kind of artifact is this?&quot; — instead of a per-repo guess, and a declared escape hatch when the answer is genuinely new.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>host/scripts/check-project-layout.py</code> (closed set, copies, per-domain trees).</li><li><code>host/scripts/project-frontmatter.py</code> (ADR-0163 metadata, in every tree).</li><li><code>host/project/README.md</code> — the one-screen map.</li></ul><h2 id="revisit-if" tabindex="-1">Revisit if <a class="header-anchor" href="#revisit-if" aria-label="Permalink to “Revisit if”">​</a></h2><ul><li>A repo needs a ninth artifact type for more than two months; add it here by superseding this ADR rather than by adding a directory.</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};